(()=>{const carousel=document.querySelector('.product-banners');if(!carousel)return;const slides=[...carousel.querySelectorAll('.banner-slide')],dots=[...carousel.querySelectorAll('[data-slide]')],pause=carousel.querySelector('.banner-pause'),status=carousel.querySelector('.banner-status');const reduced=matchMedia('(prefers-reduced-motion: reduce)');let current=0,paused=reduced.matches,hovered=false,focused=false,timer;function show(index,announce=true){current=(index+slides.length)%slides.length;slides.forEach((slide,i)=>slide.hidden=i!==current);dots.forEach((dot,i)=>dot.setAttribute('aria-pressed',String(i===current)));if(announce)status.textContent=(current+1)+' of '+slides.length+': '+slides[current].getAttribute('aria-label').replace(/^View /,'').replace(/ details$/,'');}function sync(){clearInterval(timer);pause.setAttribute('aria-pressed',String(paused));pause.setAttribute('aria-label',paused?'Resume poster rotation':'Pause poster rotation');pause.textContent=paused?'▶':'Ⅱ';if(!paused&&!hovered&&!focused&&!document.hidden)timer=setInterval(()=>show(current+1,false),7000);}carousel.querySelector('.banner-prev').addEventListener('click',()=>{show(current-1);sync()});carousel.querySelector('.banner-next').addEventListener('click',()=>{show(current+1);sync()});dots.forEach((dot,i)=>dot.addEventListener('click',()=>{show(i);sync()}));pause.addEventListener('click',()=>{paused=!paused;sync()});carousel.addEventListener('mouseenter',()=>{hovered=true;sync()});carousel.addEventListener('mouseleave',()=>{hovered=false;sync()});carousel.addEventListener('focusin',()=>{focused=true;sync()});carousel.addEventListener('focusout',e=>{if(!carousel.contains(e.relatedTarget)){focused=false;sync()}});carousel.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();show(current+(e.key==='ArrowRight'?1:-1));sync()}});document.addEventListener('visibilitychange',sync);reduced.addEventListener('change',e=>{if(e.matches)paused=true;sync()});show(0,false);sync()})();
